"""Build one merged proposal from merged-2026-10-28/content.json; no publishing."""
from pathlib import Path
from datetime import date
import json, html, hashlib, csv
ROOT=Path(__file__).resolve().parent
HERE=ROOT/'merged-2026-10-28'
data=json.loads((HERE/'content.json').read_text(encoding='utf-8'))
posts=data['posts']; main=[p for p in posts if p['role']=='Main']
e=lambda x:html.escape(str(x),quote=True)
statuses=['Planned','Manual review – changes needed','Manual review – confirmed','Drafted','Scheduled','Posted','Skipped']
assert len({p['id'] for p in posts})==len(posts)
assert len({p['date'] for p in main})==len(main),'Competing main posts'
assert len({a for p in main for a in p['assets']})==sum(len(p['assets']) for p in main),'Repeated main media'
for p in posts:
    for a in p['assets']:assert (ROOT/a).is_file(),a
    if p['role']=='Main':assert p['assets'] or p['frames'],p['id']
    p['media_ready']=bool(p['assets'])
    p['content_hash']=hashlib.sha256(json.dumps({k:p[k] for k in ['date','caption','assets','visual']},sort_keys=True).encode()).hexdigest()[:16]
def select(p):
    return f'<select class="st" data-key="{p["id"]}" aria-label="Status: {e(p["title"])}">'+''.join(f'<option>{e(s)}</option>' for s in statuses)+'</select>'
def media(p):
    out=[]
    for a in p['assets']:
        if a.endswith('.mp4'):out.append(f'<div><video controls playsinline preload="none" aria-label="{e(p["alt"])}" src="{e(a)}"></video><a href="{e(a)}" download>Download MP4</a></div>')
        else:out.append(f'<a href="{e(a)}" target="_blank" rel="noopener"><img loading="lazy" src="{e(a)}" alt="{e(p["alt"])}"></a>')
    if not out:out=[f'<div class="missing"><b>{e(p["production"])}</b><p>No final MP4 exists. The shot list is a production brief.</p></div>' if p['frames'] else '<p>Text-only listening task; no media required.</p>']
    return '<div class="media">'+''.join(out)+'</div>'
rows=[];cards=[]
for p in posts:
    day=date.fromisoformat(p['date']).strftime('%d %b')
    ready='Media exported' if p['media_ready'] else 'Video needed' if p['frames'] else 'Text task'
    rows.append(f'<tr class="post" data-id="{p["id"]}"><td>{day}<span class="small">{p["time"]} Sydney</span></td><td><a href="#{p["id"]}">{e(p["title"])}</a><span class="small">{e(p["channel"])} · {e(p["format"])} · {e(p["role"])}</span></td><td><span class="pill {"ok" if p["media_ready"] else "need"}">{ready}</span></td><td>{select(p)}</td><td><a href="#{p["id"]}">Details ↓</a></td></tr>')
    shots='<ol>'+''.join(f'<li>{e(s)}</li>' for s in p['frames'])+'</ol>' if p['frames'] else ''
    link=f'<a class="tracked-link" href="{e(p["destination"])}" target="_blank" rel="noopener">{e(p["destination"])}</a>' if p['destination'] else 'No outbound link for this listening item.'
    comment='<div class="copy-block"><b>First comment</b><button class="copy-text">Copy</button><pre>'+e(p['first_comment'])+'</pre></div>' if p['first_comment'] else ''
    parent=f'<p class="small">Companion to <a href="#{p["parent_id"]}">{e(p["parent_id"])}</a>.</p>' if p.get('parent_id') else ''
    cards.append(f'''<details class="card" id="{p['id']}"><summary><b>{day} · {e(p['title'])}</b><span>{e(p['channel'])} · {e(p['format'])} · {ready}</span></summary><div class="card-inner"><div class="card-head"><p>{p['date']} · {p['time']} Sydney · {e(p['goal'])}</p>{select(p)}</div><p class="saved-warning" hidden></p><div class="cols"><div>{media(p)}<details><summary>Production brief, alt text &amp; sources</summary><p>{e(p['visual'])}</p>{shots}<p><b>Alt text:</b> {e(p['alt'])}</p><p class="small">Merged sources: {e(', '.join(p['source_ids']))}</p></details>{parent}</div><div><label for="caption-{p['id']}"><b>Caption · edit here</b></label><textarea class="tx" id="caption-{p['id']}" data-id="{p['id']}">{e(p['caption'])}</textarea><div class="actions"><button class="copy-caption">Copy caption</button><button class="restore">Restore reviewed source</button><span class="tx-state small"></span></div><p><b>Next step:</b> {e(p['cta'])}<br><b>Link placement:</b> {e(p['link_placement'])}</p>{link}{comment}<label for="comment-{p['id']}"><b>Your review / changes needed</b></label><textarea class="cm" id="comment-{p['id']}" data-id="{p['id']}" rows="3"></textarea><details class="prior-review" hidden><summary>Earlier browser review · preserved</summary><pre></pre></details><p class="small">Media exported means the file exists. Approval, native draft, scheduling and publication are separate checks.</p></div></div><a href="#posts">↑ Calendar</a></div></details>''')
decisions=[]
for p in data['decisions']:
    targets=', '.join(f'<a href="#{t}">{e(t)}</a>' for t in p['targets']) or '—'
    decisions.append(f'<tr id="archive-{p["id"]}" data-archive-id="{p["id"]}"><td><b>{e(p["id"])}</b><br>{e(p["original_date"])}</td><td>{e(p["title"])}<details><summary>Original source record</summary><pre>{e(json.dumps(p["original"],ensure_ascii=False,indent=2))}</pre></details><span class="archive-review small"></span></td><td>{e(p["decision"])}<p>{e(p["reason"])}</p>{targets}</td></tr>')
legacy=json.loads((ROOT/'_reference/prelaunch-week-1.json').read_text(encoding='utf-8'))
history=''.join(f'<tr><td>{e(p["date"])} · {e(p["time"])}</td><td>{e(p["theme"])}</td><td>{e(p["status"])}</td></tr>' for p in legacy['posts'])
video_rows=''.join(f'<tr><td>{p["date"]}</td><td><a href="#{p["id"]}">{e(p["title"])}</a></td><td>{e(p["production"])}</td></tr>' for p in main if p['frames'])
sources=''.join(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener">{e(s["title"])}</a></li>' for s in data['sources'])
css=(HERE/'plan.css').read_text(encoding='utf-8')
sections=(HERE/'review-sections.html').read_text(encoding='utf-8').replace('VIDEO_ROWS',video_rows).replace('SOURCE_LINKS',sources)
filters=''.join(f'<label>{label}<select id="{id}"><option value="">All</option>'+''.join(f'<option>{e(v)}</option>' for v in values)+'</select></label>' for id,label,values in [('f-channel','Channel',sorted({p['channel'] for p in posts})),('f-role','Role',sorted({p['role'] for p in posts})),('f-format','Format',sorted({p['format'] for p in posts})),('f-status','Review',statuses)])
page=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DigiStayBook · merged marketing plan</title><style>{css}</style></head><body><header><div class="eyebrow">DIGISTAYBOOK / MARKETING / UPDATED 28 OCTOBER 2026</div><h1>A useful welcome.<br>A clearer route to the demo.</h1><p>One merged proposal · 29 October–29 November · Sydney time. Host stories, practical help, real product demonstrations and a first-property invitation.</p><p>The NAS is the shared master. Dates are proposed; this review has not posted, scheduled or changed anything in Meta.</p></header><div class="layout"><aside><details id="toc" open><summary>Contents</summary><ul><li><a href="#overview">What changed</a></li><li><a href="#posts">One working calendar</a></li><li><a href="#traffic">Traffic review</a></li><li><a href="#production">Videos still needed</a></li><li><a href="#scorecard">Measurement</a></li><li><a href="#details">Post details</a></li><li><a href="#archive">98 source decisions</a></li><li><a href="#existing">Preserved records</a></li><li><a href="#files">Files &amp; sources</a></li></ul></details></aside><main>
<section id="overview"><h2>The revised mix</h2><div class="summary-grid"><div><b>20</b><span>Main Facebook posts · 8 Reels + 12 image units</span></div><div><b>15/20</b><span>Main posts with exported media · 5 new videos needed</span></div><div><b>8 + 7</b><span>Pins + Stories · conditional on channel access</span></div><div><b>98</b><span>Original ideas reviewed · decisions retained</span></div></div><div class="box"><b>All main posts and Pins have a visual format.</b> Twelve main image units, three existing videos, eight Pins and seven Stories have actual files. Five Reel slots remain production briefs. The three optional community tasks are text-only listening.</div><p>Facebook is the primary test; Pinterest is evergreen support if its account is available. Instagram and YouTube can reuse approved videos once accounts and links are checked; they do not add competing main slots. TikTok, LinkedIn and email remain in reserve.</p><div class="box warn"><b>Preserve tonight’s recorded post.</b> Existing source notes say “Every home has a story” was scheduled for <b>28 October, 7:30 pm Sydney</b>, brought forward from 29 October. This is a recorded status, not a live Meta check. Do not add it again. The next host-story photo is 9 November.</div><p class="small">Keep near-identical main concepts at least 7 days apart, preferably 14. No main image or video repeats here. Cross-channel reuse and a companion Story support one idea. If a video is not ready, leave the slot empty or choose a genuinely different approved piece; a storyboard is not a Reel.</p></section>
<section id="posts"><h2>One working calendar</h2><p>38 items: 20 main Facebook posts, eight optional Pins, seven Stories and three optional listening tasks. Approximately four to five main posts a week. Times are practical tests, not verified best posting times.</p><div class="filters"><label>When<select id="f-when"><option value="all">Full proposal</option><option value="upcoming">From today</option><option value="week">Next 7 days</option></select></label>{filters}<label>Media<select id="f-media"><option value="">All readiness</option><option value="ready">Exported media</option><option value="missing">Production needed</option></select></label><label>Search<input id="search" type="search" placeholder="Topic, caption or ID"></label><span id="shown" class="small"></span></div><p class="legend">Approved in this browser: <b id="ready-count">0</b> · Recorded as posted: <b id="live-count">0</b> · <span id="status-counts"></span></p><div class="table-wrap"><table id="t"><thead><tr><th>Date</th><th>Post &amp; placement</th><th>Media</th><th>Review status</th><th>Details</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="small">Older browser reviews remain preserved. Changed copy/dates need a fresh review; an old approval is not applied automatically. Earlier Scheduled/Posted browser records are shown for reconciliation. These controls do not update Meta. Export before changing computers.</p></section>
{sections}
<section id="details"><h2>Post details &amp; finished artwork</h2><p>Expand an item for its caption, actual files, tracked destination and production notes. Calendar filters also filter these cards.</p>{''.join(cards)}</section>
<details class="panel" id="archive"><summary>98 source decisions · duplicates kept out of the queue</summary><p>Every original month item, priority-campaign item, new media-pack unit and later-week idea has a decision. This is a reference archive, not a second posting schedule. Original files and earlier browser reviews are preserved.</p><div class="table-wrap"><table><thead><tr><th>Source / old date</th><th>Original idea</th><th>Decision and retained item</th></tr></thead><tbody>{''.join(decisions)}</tbody></table></div></details>
<details class="panel" id="existing"><summary>Preserved publication records</summary><p><b>28 October 19:30 Sydney:</b> {e(data['recorded_schedule']['title'])} · {e(data['recorded_schedule']['status'])}. <a href="{e(data['recorded_schedule']['asset'])}">Original artwork</a>. Do not repost from the archived 29 October date. <span id="recorded-browser-status"></span></p><p>These seven earlier launch-week statuses are unchanged source records, not current Meta verification.</p><table><thead><tr><th>Original slot</th><th>Post</th><th>Recorded status</th></tr></thead><tbody>{history}</tbody></table></details>
</main></div><div class="bar"><span id="count" role="status">Local reviews</span><button id="copy">Copy my review</button><button id="download">Download review</button><button id="print">Print plan</button></div><script id="marketing-content" type="application/json">{json.dumps(data,ensure_ascii=False).replace('<',chr(92)+'u003c')}</script><script>{(ROOT/'marketing-review.js').read_text(encoding='utf-8')}</script></body></html>'''
(ROOT/'MARKETING_PLAN.html').write_text(page,encoding='utf-8')
fields=['id','date','channel','role','format','title','destination','published_url','reach','outbound_clicks','tagged_landing_sessions','verified_signups','attributed_first_properties','saves','useful_host_replies','production_minutes','notes']
score=HERE/'scorecard.csv'
if not score.exists():
    with score.open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
        for p in posts:w.writerow({k:p.get(k,'') for k in fields})
print(f'Built {len(posts)} active items; {len(main)} main; {sum(p["media_ready"] for p in main)} main media exported; {len(data["decisions"])} retained decisions.')
